import{n as m,t as l}from"./chunk-CDN9hKcv.js";import{E as i}from"./main-IIRSYKQX.js";import{a as l$1}from"./chunk-BGlpxNBN.js";var u=[{slug:`bulgaria`,name:`Bulgaria`,theme:`Monasteries, mountains and village life`,introduction:`Explore Bulgaria through its monasteries, mountain villages and living traditions. Enjoy the calm of frescoed monastery courtyards, unhurried afternoons in the mountains, and long tables of food cooked the way it always has been.`,guideSlugs:[`bulgaria-classic-women-only-tour-comparison`,`10-unmissable-places-to-visit-on-your-bulgaria-trip`,`the-complete-visitor-guide-to-rila-monastery`]},{slug:`kyrgyzstan`,name:`Kyrgyzstan`,theme:`Mountain lakes and nomadic traditions`,introduction:`Yurt stays, mountain landscapes and time beside Song Kul Lake are part of Omaya’s Kyrgyzstan journeys. Settle into the stillness of the high summer pastures, evenings with the families who host you, and the long golden light over the lake.`,guideSlugs:[`how-to-visit-song-kul-lake-in-kyrgyzstan`,`women-only-kyrgyzstan-what-to-expect`,`song-kul-yurt-stay-packing-guide`]},{slug:`morocco`,name:`Morocco`,theme:`Blue cities, medinas and desert dunes`,introduction:`Follow Morocco’s Blue Cities & Golden Dunes itinerary through its cities, mountains and Sahara landscapes. Enjoy mint tea in the blue lanes of Chefchaouen, the colour and noise of the medinas, and a night under more stars than you thought the sky held.`,guideSlugs:[`morocco-casablanca-marrakech-route-guide`]},{slug:`algeria`,name:`Algeria`,theme:`An expedition into the Tadrart Rouge`,introduction:`Omaya’s Algeria journey focuses on the Tadrart Rouge: red dunes, sandstone formations and desert camping. Feel the deep silence of the Sahara, sandstone arches burning red at sunset, and nights spent sleeping out beneath the stars.`,guideSlugs:[`tassili-najjer-national-park-algeria-guide`]},{slug:`india`,name:`India`,theme:`Cities, cave temples, tiger forests and the Ganga`,introduction:`India comes in two journeys with Omaya. One moves from the rush of Mumbai, with the lunchtime rhythm of its dabbawalas, to the cave temples of Ellora and Ajanta and the sal forests of Kanha, where the jeeps roll out at dawn in search of tigers. The other, for women only, crosses the north: the old lanes of Delhi, the pink walls of Jaipur, the Taj Mahal at Agra and the ghats of Varanasi, where the city wakes up slowly along the Ganga.`,guideSlugs:[`dharavi-mumbai-guide`]},{slug:`namibia`,name:`Namibia`,theme:`Canyon, red dunes, the Atlantic coast and the waterholes of Etosha`,introduction:`Namibia is a country of very long roads and very few people, and the land does most of the talking. The Fish River Canyon drops away in folds of rock at your feet; at Sossusvlei the dunes turn from apricot to deep red as the sun climbs, and the dead camel thorn trees of Deadvlei stand on white clay where they have stood for centuries. Then the desert runs straight into the cold Atlantic at Swakopmund, the granite of Spitzkoppe glows at dusk, and in Etosha the animals come to the waterholes as the light goes. Omaya’s women-only journey begins across the border in Cape Town and follows that whole road north to Windhoek.`,guideSlugs:[`cape-town-to-windhoek-namibia-guide`]}].map(e=>{let a=l$1.filter(t=>t.destination.country.toLowerCase()===e.slug);if(!a.length)throw new Error(`No tours for destination ${e.slug}`);return m(l({},e),{tours:a,heroImage:a[0].heroImage,guides:i.filter(t=>e.guideSlugs.includes(t.slug))})});export{u as t};